mapper.select:
SELECT COALESCE(MAX(seq), 0)
FROM agent_run_trace
WHERE run_id = #{runId}

SELECT id, trace_id, run_id, seq, trace_type, payload_ref, summary, created_at
FROM agent_run_trace
WHERE run_id = #{runId}
ORDER BY seq ASC
LIMIT #{limit}

SELECT id, trace_id, run_id, seq, trace_type, payload_ref, summary, created_at
FROM agent_run_trace
WHERE run_id = #{runId}
  AND seq > #{lastSeq}
ORDER BY seq ASC
LIMIT #{limit}
